import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUSES: Array<{ value: ProjectStatus; label: string; tone: 'success' | 'warning' | 'danger' }> = [
  { value: 'active', label: 'Активные', tone: 'success' },
  { value: 'paused', label: 'На паузе', tone: 'warning' },
  { value: 'over', label: 'Превышен лимит', tone: 'danger' },
];

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Портал самообслуживания', used: 42, quota: 100, status: 'active' },
  { id: 'p2', name: 'Мобильное приложение', used: 88, quota: 100, status: 'active' },
  { id: 'p3', name: 'Аналитика продаж', used: 61, quota: 100, status: 'paused' },
  { id: 'p4', name: 'Миграция биллинга', used: 100, quota: 100, status: 'over' },
  { id: 'p5', name: 'Внутренняя вики', used: 17, quota: 100, status: 'paused' },
  { id: 'p6', name: 'Интеграция с CRM', used: 73, quota: 100, status: 'active' },
  { id: 'p7', name: 'Поисковый индекс документов и вложений', used: 95, quota: 100, status: 'over' },
  { id: 'p8', name: 'Дизайн-система', used: 34, quota: 100, status: 'active' },
  { id: 'p9', name: 'Отчёты для регулятора', used: 56, quota: 100, status: 'paused' },
  { id: 'p10', name: 'Сервис уведомлений', used: 29, quota: 100, status: 'active' },
  { id: 'p11', name: 'Архив старых заказов', used: 81, quota: 100, status: 'over' },
];

export default function ProjectQuotaPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(['active', 'paused', 'over']);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const rows = visible.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setStatuses((current) => current.filter((value) => value !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUSES.map((status) => status.value));
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {STATUSES.filter((status) => statuses.includes(status.value)).map((status) => (
          <JxChip
            key={status.value}
            active
            removable
            onRemove={() => removeStatus(status.value)}
          >
            {status.label}
          </JxChip>
        ))}
        {statuses.length < STATUSES.length && (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        )}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Проектов по этим фильтрам нет"
          message="Все статусы сняты. Верните фильтры, чтобы снова увидеть расход по квотам."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: 8,
            }}
          >
            {rows.map((project) => {
              const status = STATUSES.find((item) => item.value === project.status)!;
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 16,
                    padding: 12,
                    borderRadius: 'var(--jx-r)',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                  }}
                >
                  <JxProgressCircle
                    value={project.used}
                    max={project.quota}
                    showValue
                    aria-label={`Квота проекта «${project.name}»`}
                  />
                  <span
                    style={{
                      flex: 1,
                      minWidth: 0,
                      color: 'var(--jx-text)',
                      fontFamily: 'var(--jx-font-sans)',
                      overflowWrap: 'anywhere',
                    }}
                  >
                    {project.name}
                  </span>
                  <JxBadge tone={status.tone} dot>
                    {status.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

